/**
 * =============================================================================
 * KS-764 — the revoke ARM is bound to its CALL SITES (QA F-764-02)
 * =============================================================================
 * `decideKeyRevoke` had eleven passing cases and none of them could tell whether
 * a route actually PASSED the key's organisation into it. Deleting
 * `organizationId: apiKey.organizationId` from services/security's call site
 * re-opened KS-764 with the whole policy suite still green — the arm was
 * correct and unreachable, which is indistinguishable from absent at runtime.
 *
 * A policy test proves the rule. This proves the WIRING, for every call site at
 * once, so a second route cannot be added later that quietly omits the field —
 * which is exactly how originate's sibling route (F-764-01) came to exist.
 *
 * It is a SOURCE guard rather than an HTTP test. What it cannot see is runtime
 * behaviour — stated in the suite's own name and here, not implied away.
 *
 * ⚠ CORRECTED (Peter's #799 review): the reason previously given for that choice
 * was WRONG, and a wrong reason for a real gap is the worse half — it forecloses
 * the fix. It said both call sites "live in service entrypoints whose import
 * graph boots a server, a database pool and a cache". That is false for
 * `services/security`: `ks742-keys-tenancy-route-contract.test.ts` (298 lines,
 * in-tree) already boots the real app under `SECURITY_DISABLE_BOOT=1` with NO
 * database, listens on port 0 and drives real HTTP with RS256 tokens minted by
 * node crypto. Its own header says of this very route: *"Delete the route's
 * `if (!decision.allow)` block and that suite stays green. This file is the wire
 * test it lacked."*
 *
 * It is also weaker than it looks for `services/originate`: `index.ts:326` does
 * call `app.listen` unconditionally, but `adminConfigRouter` is exported
 * separately, and `ks563-certified-vs-anchored.test.ts` already mounts a router
 * on a bare express app and drives it over HTTP.
 *
 * So the honest statement is: **this guard proves the WIRING and no wire test
 * exists yet for the 403 on either surface.** That gap is real, it is tracked,
 * and it is not blocked by the obstacle previously claimed — the precedent for
 * closing it is sitting in the same repository.
 * =============================================================================
 */

import { describe, it, expect } from 'vitest';
import { readFileSync, existsSync, readdirSync, writeFileSync, rmSync, mkdtempSync, mkdirSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, resolve, relative, sep } from 'node:path';

function findDevRoot(start: string): string {
  let dir = start;
  for (let i = 0; i < 10; i++) {
    if (existsSync(join(dir, 'services')) && existsSync(join(dir, 'packages'))) return dir;
    const parent = resolve(dir, '..');
    if (parent === dir) break;
    dir = parent;
  }
  throw new Error(`[ks764 call-site guard] could not locate the Dev root from ${start}`);
}

const DEV_ROOT = findDevRoot(process.cwd());

/**
 * Every route that revokes an API key. Both were found by sweeping for writes
 * that set `is_active = false` on `svc_api_keys` (2026-09-03): these are the two
 * that exist. `tokenisation`'s key routes mint and rotate CRYPTO keys against a
 * different table and are correctly absent.
 *
 * A third revoke surface added later without the organisation arm fails the
 * "every call site" case below only if it is listed here — so the sweep case
 * after it independently re-derives the list from the tree.
 */
const CALL_SITES = [
  {
    name: 'services/security DELETE /api/keys/:id',
    file: 'services/security/src/index.ts',
    // The two sites revoke by different mechanisms and that is legitimate:
    // security flips the in-memory record and upserts it, originate issues a
    // scoped UPDATE. One regex over both would only have matched by being loose
    // enough to mean nothing, so each site names its own write.
    revokeWrite: /isActive\s*=\s*false;[\s\S]{0,80}dbSaveApiKey\(/,
  },
  {
    name: 'services/originate DELETE /api/admin/api-keys/:id',
    file: 'services/originate/src/routes/adminConfig.ts',
    revokeWrite: /UPDATE svc_api_keys SET is_active = false/,
  },
];

/**
 * The two mechanisms by which this codebase deactivates an `svc_api_keys` row.
 *
 * Deliberately NOT one loose regex over both: security flips an in-memory record
 * and upserts it, originate issues a scoped UPDATE, and a pattern general enough
 * to cover both would match anything mentioning a key. Each mechanism is named,
 * so a miss is a miss of a KNOWN shape rather than of an unbounded one — and a
 * third mechanism invented later is a deliberate act that has to be added here.
 */
const REVOKE_WRITES = [
  /UPDATE\s+svc_api_keys\s+SET\s+is_active\s*=\s*false/i,
  /isActive\s*=\s*false;[\s\S]{0,80}dbSaveApiKey\(/,
];

/**
 * Every `services/*` and `packages/*` `src` TypeScript file, excluding tests.
 *
 * QA F-799-09: `packages/*` was NOT walked, and the omission was invisible —
 * **`packages/shared/src/security/keyRevokePolicy.ts`, the module this entire
 * suite exists for, sat outside the swept corpus.** Widening takes it from 366
 * files to 454 (measured), and is what lets the drift sweep below see the policy
 * module at all.
 *
 * @param root - tree to walk. Defaults to the live Dev root; the probe case
 *   passes a temporary fixture tree (QA F-799-10), so the guard-on-the-guard no
 *   longer writes into real source in order to prove the sweep can see.
 */
function sourceFiles(root: string = DEV_ROOT): string[] {
  const out: string[] = [];
  const walk = (dir: string): void => {
    for (const entry of readdirSync(dir, { withFileTypes: true })) {
      const full = join(dir, entry.name);
      if (entry.isDirectory()) {
        // __tests__ carries both patterns as fixtures — including this file
        // itself — so sweeping them would report the guards as surfaces.
        if (entry.name === '__tests__' || entry.name === 'node_modules' || entry.name === 'dist')
          continue;
        walk(full);
      } else if (entry.name.endsWith('.ts') && !entry.name.endsWith('.test.ts')) {
        out.push(full);
      }
    }
  };
  for (const group of ['services', 'packages']) {
    const groupRoot = join(root, group);
    if (!existsSync(groupRoot)) continue;
    for (const pkg of readdirSync(groupRoot, { withFileTypes: true })) {
      if (!pkg.isDirectory()) continue;
      const src = join(groupRoot, pkg.name, 'src');
      if (existsSync(src)) walk(src);
    }
  }
  return out;
}

/**
 * The OVER-BROAD drift sweep (QA F-799-09): every file mentioning the table AND
 * the column, by any spelling.
 *
 * The narrow sweep matches two exact mechanisms, which is deliberate — but it
 * means a NEW revoke surface in a third idiom (`SET updated_at = NOW(),
 * is_active = false`, an ORM call, a `.js`/`.mjs` file) is invisible, leaving
 * the equality case GREEN with an unguarded surface in the tree. **That is the
 * precise failure that case advertises catching.**
 *
 * This sweep cannot be fooled by idiom. It over-matches on purpose — reads,
 * migrations and the policy module all mention both — so its result is asserted
 * against CALL_SITES plus a NAMED allowlist. **A new file mentioning both then
 * forces a human decision: either it revokes and belongs in CALL_SITES, or it
 * does not and belongs in the allowlist with a reason.** Neither is a silent pass.
 */
function sweepTableMentions(root: string = DEV_ROOT): string[] {
  return sourceFiles(root)
    .filter((f) => {
      const src = readFileSync(f, 'utf8');
      return src.includes('svc_api_keys') && src.includes('is_active');
    })
    .map((f) => relative(root, f).split(sep).join('/'));
}

/**
 * Files that mention the table and column but do NOT revoke. Each carries a
 * reason: this list is the drift sweep's escape hatch, and an unexplained entry
 * would defeat it.
 */
const NON_REVOKE_MENTIONS = [
  {
    file: 'packages/shared/src/security/keyRevokePolicy.ts',
    why: 'the policy module itself — it DECIDES revocation and never writes the row',
  },
  {
    file: 'services/api-gateway/src/startup-migrations.ts',
    why: 'DDL creating the column; it deactivates no key',
  },
];

/**
 * Re-derive the revoke surfaces FROM THE TREE (QA F-799-01).
 *
 * @returns repo-relative-to-Dev paths, POSIX-separated so the comparison is
 *          stable on Windows checkouts as well as macOS and Linux.
 */
function sweepRevokeSurfaces(root: string = DEV_ROOT): string[] {
  return sourceFiles(root)
    .filter((f) => {
      const src = readFileSync(f, 'utf8');
      return REVOKE_WRITES.some((re) => re.test(src));
    })
    .map((f) => relative(root, f).split(sep).join('/'));
}

/** The argument object of each `decideKeyRevoke(` call in a source file. */
function decideKeyRevokeCallArgs(src: string): string[] {
  const out: string[] = [];
  let idx = src.indexOf('decideKeyRevoke(');
  while (idx !== -1) {
    // Walk from the opening paren to its match, so nested braces/parens are safe.
    let depth = 0;
    let i = idx + 'decideKeyRevoke'.length;
    const start = i;
    for (; i < src.length; i++) {
      if (src[i] === '(') depth++;
      else if (src[i] === ')') {
        depth--;
        if (depth === 0) break;
      }
    }
    out.push(src.slice(start, i + 1));
    idx = src.indexOf('decideKeyRevoke(', i);
  }
  return out;
}

describe('KS-764 — the organisation arm is wired at every revoke call site', () => {
  for (const site of CALL_SITES) {
    describe(site.name, () => {
      const src = readFileSync(join(DEV_ROOT, site.file), 'utf8');
      const calls = decideKeyRevokeCallArgs(src);

      it('calls decideKeyRevoke at all (positive control for the parser)', () => {
        // Without this, a rename would empty `calls` and every assertion below
        // would vacuously pass over an empty array.
        expect(calls.length).toBeGreaterThan(0);
      });

      it('passes the KEY OWN organisation into the decision', () => {
        // The deletion the QA named: remove `organizationId: …` here and this
        // goes red while all eleven policy cases stay green.
        for (const call of calls) {
          expect(call).toMatch(/organizationId\s*:/);
        }
      });

      it('passes the key TENANT into the decision', () => {
        // The KS-643 half. It shares the failure mode: correct policy, unwired.
        for (const call of calls) {
          expect(call).toMatch(/tenantId\s*[,:]/);
        }
      });

      it('resolves the key BEFORE deciding, never from the request body', () => {
        // "Resolve first, then authorise" — the comparison needs the key's own
        // organisation, and a body-supplied one would let the caller choose the
        // answer. Neither call site may read organizationId off req.body.
        for (const call of calls) {
          expect(call).not.toMatch(/req\.body/);
        }
      });

      it('refuses when the decision refuses', () => {
        // A wired call whose result is discarded is not a gate. Both sites must
        // branch on `decision.allow` being false.
        expect(src).toMatch(/if\s*\(\s*!\s*decision\.allow\s*\)/);
      });
    });
  }

  it('CALL_SITES matches every revoke surface written in the TWO KNOWN IDIOMS under services/* and packages/*', () => {
    // QA F-799-01. The previous version of this case did NOT read the tree: it
    // mapped CALL_SITES to file names and compared them against a second literal
    // three lines below, in this same file. Two hand-written lists agreeing with
    // each other is not a derivation — a third revoke surface added tomorrow left
    // it green, which is the exact failure it advertises catching. Its comment
    // also claimed to be "the case that would have caught F-764-01"; that was
    // false, because back then both arrays held one entry and matched.
    //
    // MEASURED, one variable: with a third surface planted in the tree, this
    // version fails (3 found vs 2 listed) and the version at 124e98192 PASSES.
    //
    // It now walks services/*/src for the two mechanisms by which this codebase
    // deactivates an svc_api_keys row, and compares what it FINDS against
    // CALL_SITES. Tests are excluded: they contain both patterns as fixtures.
    const found = sweepRevokeSurfaces().sort();
    const listed = CALL_SITES.map((s) => s.file).sort();

    // POSITIVE CONTROL, before the equality is trusted: a sweep that returns
    // nothing — a moved directory, a renamed table, a regex that stopped
    // matching — is indistinguishable from "no new surfaces" at the assertion
    // below, and would green this case forever.
    expect(found.length).toBeGreaterThan(0);

    expect(found).toEqual(listed);

    // And each listed file really does write the revoke, by its own mechanism.
    for (const site of CALL_SITES) {
      const src = readFileSync(join(DEV_ROOT, site.file), 'utf8');
      expect(src).toMatch(site.revokeWrite);
    }
  });

  it('the sweep can SEE a new revoke surface (the guard on the guard)', () => {
    // Without this, the case above passes equally well if the sweep is blind.
    //
    // QA F-799-10: this used to write `__ks764_sweep_probe__.ts` into the LIVE
    // tree at services/security/src/. Cleanup was well built — try/finally, a
    // pre-check refusing to overwrite real source, a post-assertion it is gone —
    // but three hazards survived it: `finally` does not run on SIGKILL, a CI
    // timeout or OOM, and the residue then made the OTHER case fail
    // 3-found-vs-2-listed with a message naming none of this; a concurrent
    // `tsc`, build, watcher or lint over that service saw an uncompilable file
    // (top-level `await` against an undefined `db`); and it dirtied `git status`
    // in a repo whose discipline treats a clean tree as checkable.
    //
    // **A control must not mutate its subject.** The sweep is parameterised on a
    // root, so the probe now builds its own throwaway tree. Identical guard
    // strength, zero mutation, and nothing to leak if the process is killed —
    // the OS reclaims a tmpdir; it does not reclaim a file in your source tree.
    const fixture = mkdtempSync(join(tmpdir(), 'ks764-sweep-'));
    try {
      const probeDir = join(fixture, 'services', 'probe-svc', 'src');
      mkdirSync(probeDir, { recursive: true });
      writeFileSync(
        join(probeDir, 'revoker.ts'),
        'await db.query("UPDATE svc_api_keys SET is_active = false WHERE id=$1");\n',
      );
      // A file that mentions neither pattern must NOT be reported — otherwise a
      // sweep returning everything would pass this case.
      writeFileSync(join(probeDir, 'innocent.ts'), 'export const x = 1;\n');

      const found = sweepRevokeSurfaces(fixture);
      expect(found).toContain('services/probe-svc/src/revoker.ts');
      expect(found).not.toContain('services/probe-svc/src/innocent.ts');

      // And the widened walk really does reach packages/*, not just services/*.
      const pkgDir = join(fixture, 'packages', 'probe-pkg', 'src');
      mkdirSync(pkgDir, { recursive: true });
      writeFileSync(
        join(pkgDir, 'revoker.ts'),
        'await db.query("UPDATE svc_api_keys SET is_active = false WHERE id=$1");\n',
      );
      expect(sweepRevokeSurfaces(fixture)).toContain('packages/probe-pkg/src/revoker.ts');
    } finally {
      rmSync(fixture, { recursive: true, force: true });
    }
  });

  it('no file mentions svc_api_keys + is_active except the call sites and a NAMED allowlist', () => {
    // QA F-799-09 — the drift guard, and the reason it exists:
    //
    // the narrow sweep matches TWO exact idioms. An EXISTING listed surface that
    // stops matching fails loudly, which is good. But a NEW surface written in a
    // third idiom is invisible, and leaves the narrow case GREEN with an
    // unguarded revoke in the tree — the precise failure it advertises catching.
    // Neither existing control closes that: `found.length > 0` proves traversal,
    // and the probe is authored to match the regex it tests, so it controls for
    // directory coverage, not idiom coverage.
    //
    // This sweep cannot be fooled by idiom, because it matches the table and the
    // column rather than the shape of the write. It over-matches on purpose, so
    // the assertion is against CALL_SITES plus a NAMED allowlist — making a new
    // mention a decision a human has to record, not a silent pass.
    const mentions = sweepTableMentions().sort();

    // POSITIVE CONTROL: a sweep finding nothing would satisfy any superset claim.
    expect(mentions.length).toBeGreaterThan(0);

    // The broad sweep must be a SUPERSET of the narrow one. If it ever is not,
    // the two disagree about the corpus and neither can be trusted.
    for (const surface of sweepRevokeSurfaces()) {
      expect(mentions).toContain(surface);
    }

    const accounted = [
      ...CALL_SITES.map((c) => c.file),
      ...NON_REVOKE_MENTIONS.map((m) => m.file),
    ].sort();

    // The message names what to do, because the failure is a judgement call and
    // the next reader will not have this comment in front of them.
    expect(
      mentions,
      'A file mentions svc_api_keys AND is_active but is neither a listed revoke ' +
        'call site nor an allowlisted non-revoke. Decide which it is: add it to ' +
        'CALL_SITES (and wire the organisation arm), or to NON_REVOKE_MENTIONS ' +
        'with a reason.',
    ).toEqual(accounted);
  });

  it('every JwtPayload type on a revoke path DECLARES the fields the policy reads', () => {
    // Peter's #799 review, finding 3. `decideTenantAccess` — which
    // `decideKeyRevoke` delegates to — reads `user.tenantId` and refuses a
    // caller without one outright (`403 caller has no tenant`,
    // keyRevokePolicy.ts:175). Neither payload type DECLARED that field.
    //
    // The routes worked anyway, because the auth service happens to sign it in
    // — and `services/auth/src/services/jwt.ts:263` signs it CONDITIONALLY,
    // `...(meta.tenantId ? { tenantId } : {})`, so a tenant-less user really
    // does receive a token without the claim.
    //
    // **An authorisation input that is load-bearing, undeclared, and invisible
    // to the compiler is the shape that surprises someone later** — it looks
    // optional in the type and is mandatory in the policy. This asserts the
    // declaration rather than trusting what a minter currently emits.
    const PAYLOAD_TYPES = [
      'packages/shared/src/middleware/index.ts',
      'services/originate/src/middleware/auth.ts',
    ];
    // The fields `decideTenantAccess` reads off the caller. Kept beside the
    // citation so a reader can check the list against the policy rather than
    // taking it on trust.
    const READ_BY_POLICY = ['tenantId', 'organizationId'];

    for (const rel of PAYLOAD_TYPES) {
      const full = join(DEV_ROOT, rel);
      expect(existsSync(full), `payload type file is gone: ${rel}`).toBe(true);
      const src = readFileSync(full, 'utf8');

      const start = src.indexOf('interface JwtPayload');
      // POSITIVE CONTROL: a rename would make every assertion below vacuous.
      expect(start, `no 'interface JwtPayload' in ${rel}`).toBeGreaterThan(-1);

      // Brace-MATCH to the interface's own close, rather than `indexOf('}')`.
      // The naive version was written first and failed on correct code: the
      // doc comment on `tenantId` contains `{ tenantId }` (quoting how auth
      // signs it), so the first `}` after the declaration sat INSIDE a comment
      // and truncated the body before the field it was looking for. A parser
      // defeated by the text it parses — caught only because the case went red
      // before any tamper.
      const open = src.indexOf('{', start);
      let depth = 0;
      let end = open;
      for (; end < src.length; end++) {
        if (src[end] === '{') depth++;
        else if (src[end] === '}') {
          depth--;
          if (depth === 0) break;
        }
      }
      const body = src.slice(open, end + 1);

      for (const field of READ_BY_POLICY) {
        expect(
          body,
          `${rel} does not declare '${field}', which decideTenantAccess reads off ` +
            'the caller. An authorisation input that the type omits is a ' +
            'dependency resting on what a token minter happens to emit.',
        ).toMatch(new RegExp(`\\b${field}\\??\\s*:`));
      }
    }
  });

  it('every allowlisted non-revoke really is present and really does NOT revoke', () => {
    // An allowlist is an assertion too. A stale entry would silently widen the
    // escape hatch, and one naming a file that DOES revoke would hide exactly
    // what this suite exists to find.
    for (const entry of NON_REVOKE_MENTIONS) {
      const full = join(DEV_ROOT, entry.file);
      expect(existsSync(full), `allowlisted file is gone: ${entry.file}`).toBe(true);
      expect(entry.why.length).toBeGreaterThan(20);
      expect(sweepRevokeSurfaces()).not.toContain(entry.file);
    }
  });
});
